<?php require_once __DIR__.'/../../includes/auth.php';require_login('admin');$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT COUNT(*) FROM services WHERE category_id=?');$s->execute([$id]);if($s->fetchColumn()>0){flash('error','Category cannot be deleted while services depend on it. Reassign or delete those services first.');redirect('admin/categories/index.php');}$s=$pdo->prepare('DELETE FROM service_categories WHERE id=?');$s->execute([$id]);log_activity('Category deletion','Deleted category '.$id);redirect('admin/categories/index.php');